css:
/* CyberDeck Prime - High Performance Animated Theme */

:root {
  /* Core Variables Override */
  --bg: #030508;
  --surface: rgba(10, 20, 40, 0.7);
  --text: #e0f7ff;
  --text-muted: #569cd6;
  --border: #00f3ff;
  --primary: #ff00ff;
  --radius: 0px;

  /* Neon Palette */
  --neon-cyan: #00f3ff;
  --neon-pink: #ff00ff;
  --neon-green: #0aff00;
  --glass-border: 1px solid rgba(0, 243, 255, 0.3);

  /* Animation Speeds */
  --grid-speed: 20s;
  --pulse-speed: 4s;
}

/* =========================================
   GLOBAL ANIMATIONS & BACKGROUND
   ========================================= */

@keyframes move-grid {
  0% { background-position: 0 0; }
  100% { background-position: 0 40px; }
}

@keyframes text-flicker {
  0% { opacity: 1; }
  5% { opacity: 0.8; }
  10% { opacity: 1; }
  100% { opacity: 1; }
}

body {
  background-color: var(--bg) !important;
  /* visual perspective grid using gradients */
  background-image: 
    linear-gradient(rgba(0, 243, 255, 0.1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 243, 255, 0.1) 1px, transparent 1px);
  background-size: 40px 40px;
  background-position: center top;
  animation: move-grid var(--grid-speed) linear infinite;
  font-family: 'Courier New', monospace !important;
  overflow-x: hidden;
}

/* CRT Scanline Overlay */
body::after {
  content: " ";
  display: block;
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.1) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.03), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.03));
  z-index: 9999;
  background-size: 100% 2px, 3px 100%;
  pointer-events: none;
}

/* =========================================
   UI COMPONENTS
   ========================================= */

/* Header - Floating HUD bar */
.header {
  background: rgba(3, 5, 8, 0.9) !important;
  border-bottom: 1px solid var(--neon-cyan) !important;
  box-shadow: 0 0 15px var(--neon-cyan) !important;
  backdrop-filter: blur(10px);
}

.brand {
  text-transform: uppercase;
  letter-spacing: 4px;
  text-shadow: 0 0 10px var(--neon-cyan);
  color: var(--neon-cyan) !important;
}

/* Cards - Holographic Glass Panels */
.card {
  background: var(--surface) !important;
  border: 1px solid var(--neon-cyan) !important;
  box-shadow: 0 0 5px rgba(0, 243, 255, 0.2), inset 0 0 20px rgba(0, 243, 255, 0.05) !important;
  backdrop-filter: blur(4px);
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

/* Card Hover - Power Up Effect */
.card:hover {
  box-shadow: 0 0 20px rgba(0, 243, 255, 0.6), inset 0 0 10px rgba(0, 243, 255, 0.2) !important;
  transform: translateY(-2px) scale(1.01);
  border-color: var(--neon-pink) !important;
  z-index: 10;
}

.card-title {
  color: var(--neon-cyan) !important;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Decorative Corner Markers on Cards */
.card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 10px; height: 10px;
  border-top: 2px solid var(--neon-pink);
  border-left: 2px solid var(--neon-pink);
  opacity: 0.7;
}

.card::after {
  content: '';
  position: absolute;
  bottom: 0; right: 0;
  width: 10px; height: 10px;
  border-bottom: 2px solid var(--neon-pink);
  border-right: 2px solid var(--neon-pink);
  opacity: 0.7;
}

/* =========================================
   INTERACTIVE ELEMENTS
   ========================================= */

/* Buttons - Glowing Pills */
.btn, .header-btn {
  border: 1px solid var(--neon-cyan) !important;
  background: transparent !important;
  color: var(--neon-cyan) !important;
  text-transform: uppercase;
  font-size: 0.7rem !important;
  letter-spacing: 1px;
  transition: 0.2s;
}

.btn:hover, .header-btn:hover {
  background: var(--neon-cyan) !important;
  color: #000 !important;
  box-shadow: 0 0 15px var(--neon-cyan);
  text-shadow: none;
}

.btn-primary {
  border-color: var(--neon-pink) !important;
  color: var(--neon-pink) !important;
}

.btn-primary:hover {
  background: var(--neon-pink) !important;
  box-shadow: 0 0 15px var(--neon-pink);
}

/* Inputs */
.search-input, .form-input, .form-textarea, .form-select {
  background: rgba(0,0,0,0.5) !important;
  border: 1px solid #333 !important;
  color: var(--neon-green) !important;
  font-family: monospace !important;
}

.search-input:focus, .form-input:focus {
  border-color: var(--neon-green) !important;
  box-shadow: 0 0 10px rgba(10, 255, 0, 0.3) !important;
}

/* Modals & Menus */
.modal, .menu-panel {
  background: rgba(5, 10, 20, 0.95) !important;
  border: 1px solid var(--neon-pink) !important;
  box-shadow: 0 0 30px rgba(255, 0, 255, 0.2) !important;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 8px;
  background: #000;
}
::-webkit-scrollbar-thumb {
  background: var(--neon-cyan);
  border-radius: 0;
}
